import{_ as t,o,c as r,a5 as n}from"./chunks/framework.CXroN2RO.js";const s="/study/images/network/tcp-data-path.svg",a="/study/images/network/tcp-framing-and-half-close.svg",g=JSON.parse('{"title":"ソケットとTCP通信 — send/recvの内部とメッセージ境界","description":"","frontmatter":{"title":"ソケットとTCP通信 — send/recvの内部とメッセージ境界","study":{"source":"新規執筆","section":"reference","format":"article","status":"published","domain":"network","summary":"IP・port・接続・ソケットを区別し、TCPの送受信バッファと順序制御、部分的なsend/recv、長さ付きフレーム、半閉鎖、アプリ側ACKと期限を説明する。","aliases":["socket","ソケット","TCP","IP","port","ポート","endpoint","listener","accept","connect","send","recv","byte stream","バイトストリーム","framing","メッセージ境界","length prefix","half-close","半閉鎖","WouldBlock","application ACK","loopback"],"verification":"一次資料照合（2026-11-04）"}},"headers":[],"relativePath":"network/tcp-sockets.md","filePath":"network/tcp-sockets.md"}'),c={name:"network/tcp-sockets.md"};function d(i,e,l,p,h,f){return o(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="ソケットとtcp通信-—-send-recvの内部とメッセージ境界" tabindex="-1">ソケットとTCP通信 — send/recvの内部とメッセージ境界 <a class="header-anchor" href="#ソケットとtcp通信-—-send-recvの内部とメッセージ境界" aria-label="Permalink to &quot;ソケットとTCP通信 — send/recvの内部とメッセージ境界&quot;">​</a></h1><p>通信の用語から確認する場合は、<a href="/study/network/network-basics.html">ネットワークの基本</a>と<a href="/study/network/ip-addresses-and-ports.html">IPアドレスとポート</a>から読み始めます。</p><p>TCPは接続した相手との間で順序のあるバイト列をやり取りする通信方式です。送信側の<code>send</code>一回が、受信側の<code>recv</code>一回やアプリのメッセージ一件に対応するわけではありません。TCPがbyteを届け、アプリの規約がbyteの意味や区切りを決めます。<a href="https://www.rfc-editor.org/rfc/rfc9293.html#section-2.2" target="_blank" rel="noreferrer">IETF RFC 9293 §2.2: Key TCP Concepts</a></p><p>ここではTCPの基本と、WindowsのWinsock／.NET 10のソケットAPIを説明します。実践は同一プロセス内のIPv4ループバック通信です。外部ネットワーク、Unity、他OSでの実行結果を含みません。</p><h2 id="ip・port・socket・接続" tabindex="-1">IP・port・socket・接続 <a class="header-anchor" href="#ip・port・socket・接続" aria-label="Permalink to &quot;IP・port・socket・接続&quot;">​</a></h2><table tabindex="0"><thead><tr><th>用語</th><th>このページでの意味</th></tr></thead><tbody><tr><td>IPアドレス</td><td>IP層で配送先などを表すアドレス。1台につき常に一つとは限らない</td></tr><tr><td>port番号</td><td>TCP内で通信先を区別する16bitの番号。プロセスIDとは別</td></tr><tr><td>エンドポイント</td><td>IPアドレスとport番号の組</td></tr><tr><td>ソケット</td><td>アプリがOSの通信状態を操作するための資源。C++では<code>SOCKET</code>、C#では<code>Socket</code>で扱う</td></tr><tr><td>TCP接続</td><td>二つのエンドポイント間で維持する通信状態</td></tr></tbody></table><p>TCPの接続は、送信元IP・送信元port・宛先IP・宛先portという<strong>4つ組</strong>で区別します。同じサーバーportへ複数のクライアントが接続できるのは、相手側のエンドポイントも含めて識別するためです。これはアプリが持つソケットのハンドル値や、ログインしたユーザーIDとは別の識別です。<a href="https://www.rfc-editor.org/rfc/rfc9293.html#section-4" target="_blank" rel="noreferrer">IETF RFC 9293 §4: connection / socket</a></p><p>サーバーは<code>bind</code>でローカルのエンドポイントを割り当て、<code>listen</code>で接続要求を待つ状態にします。この<strong>待受けソケット</strong>（listener）と、<code>accept</code>が返す<strong>接続済みソケット</strong>は別です。実際の相手との送受信は後者で行い、元のlistenerは別の接続を受け付けられます。<a href="https://learn.microsoft.com/en-us/windows/win32/api/winsock2/nf-winsock2-accept" target="_blank" rel="noreferrer">Microsoft: accept</a></p><p>クライアントは<code>connect</code>で相手を指定します。通常のTCP接続確立では、SYN・SYN/ACK・ACKを交わし、両方向のシーケンス番号などを同期します。これが<strong>3ウェイハンドシェイク</strong>です。接続成功はアプリ側のログイン成功や、任意の要求の処理完了を意味しません。<a href="https://learn.microsoft.com/en-us/troubleshoot/windows-server/networking/three-way-handshake-via-tcpip" target="_blank" rel="noreferrer">Microsoft: TCP/IPの3ウェイハンドシェイク</a></p><p>実践は<code>127.0.0.1</code>を直接指定し、名前をIPへ解決するDNSは使いません。listenerのportを0としてOSに割り当ててもらい、実際のportへクライアントを接続します。<strong>port 0を宛先にして通信する例ではありません。</strong> IPv4を選ぶのはこの例の範囲で、TCPにはIPv6で使うソケットもあります。<a href="https://learn.microsoft.com/en-us/windows/win32/api/winsock2/nf-winsock2-bind" target="_blank" rel="noreferrer">Microsoft: bind — port zero</a>、<a href="https://learn.microsoft.com/en-us/windows/win32/api/winsock2/nf-winsock2-wsasocketw" target="_blank" rel="noreferrer">WSASocket — address families</a></p><h2 id="sendから相手のrecvまで" tabindex="-1">sendから相手のrecvまで <a class="header-anchor" href="#sendから相手のrecvまで" aria-label="Permalink to &quot;sendから相手のrecvまで&quot;">​</a></h2><p>次は通常の送受信を考えるための<strong>概念上の経路</strong>です。OSごとの関数呼出しの厳密な順序や、コピー回数を固定するものではありません。</p><ol><li>アプリが送るbyte列を用意し、<code>send</code>へ範囲を渡す。OS側の送信管理へ受け入れられた分を、戻り値で確認する。</li><li>TCPがバイト列へシーケンス番号を対応させ、セグメントという転送単位にまとめる。受信確認や必要な再送を管理する。</li><li>別ホストへの通信ではIP層が配送先や経路を扱い、ネットワークインターフェースなどを通じてデータを送る。</li><li>相手側のTCPが順序や重複を管理し、アプリへ渡すバイト列を受信側のバッファに保持する。</li><li>相手の<code>recv</code>が今回取り出せたbyteを返す。アプリは蓄積したbyte列からメッセージを解析する。</li></ol><p>シーケンス番号はbyteの位置を扱い、再送しても同じデータをアプリへ重複して渡さないために使います。<strong>フロー制御</strong>は相手の受信能力に合わせて送信を制限する仕組みです。ネットワークの混雑に応じた送信量の調整である輻輳制御とも区別します。TCPの信頼性は、無限に通信が成功し続けることや、一定時間で届くことを保証しません。<a href="https://www.rfc-editor.org/rfc/rfc9293.html#section-3.8" target="_blank" rel="noreferrer">IETF RFC 9293 §2.2 / §3.8</a></p><p>OSのバッファは送受信を仲介しますが、アプリのすべてのバッファと一対一の連続領域である必要はありません。API、OS、オフロードなどで処理経路は変わり、「send一回でコピー一回」「send一回でパケット一個」とは数えません。</p><figure class="study-figure"><img src="'+s+`" alt="送信アプリからOSの送信管理、TCP、別ホストへのIP配送とネットワークインターフェース、相手のTCP受信バッファ、recvと解析へ進む概念図。ループバック実践は同一ホスト内で、物理NICや外部ネットワークの動作を測定しない。" width="760" height="1510"><figcaption><strong>sendで受け入れられる時点と、相手アプリが解析する時点を分ける。</strong> 別ホスト通信の経路は概念図です。実践の<code>127.0.0.1</code>通信は同一ホスト内で、NICや外部ネットワークを実測しません。<a href="/study/images/network/tcp-data-path.svg" target="_blank" rel="noopener noreferrer">TCPのデータ経路を拡大</a></figcaption></figure><p><strong>ループバック</strong>は、自分のホスト内へ戻す通信です。IPv4の127から始まるアドレスは、ホスト外へ出すための宛先ではありません。ローカル実験の時間や成功率から、実ネットワークの遅延・混雑・再送・NIC性能を結論しません。<a href="https://www.rfc-editor.org/rfc/rfc1122.html#section-3.2.1.3" target="_blank" rel="noreferrer">IETF RFC 1122 §3.2.1.3: loopback</a></p><h2 id="send成功、tcpのack、アプリのack" tabindex="-1">send成功、TCPのACK、アプリのACK <a class="header-anchor" href="#send成功、tcpのack、アプリのack" aria-label="Permalink to &quot;send成功、TCPのACK、アプリのACK&quot;">​</a></h2><p><code>send</code>が正の数を返しても、相手のアプリが既に受け取り、解析し、処理を終えた証拠にはなりません。Winsockの資料も、送信呼出しの成功だけでは相手への配送成功を示さないと区別しています。<a href="https://learn.microsoft.com/en-us/windows/win32/api/winsock2/nf-winsock2-send" target="_blank" rel="noreferrer">Microsoft: send — successful completion</a></p><p>TCPの<strong>ACK</strong>は、TCPがどこまでのシーケンス番号を受信確認したかを伝えるものです。相手のゲーム処理がそのデータを採用したか、保存が完了したかは別です。<a href="https://www.rfc-editor.org/rfc/rfc9293.html#section-3.1" target="_blank" rel="noreferrer">IETF RFC 9293 §3.1: Acknowledgment Number</a></p><p>アプリに必要なら、別途「要求ID 42の処理を受け付けた」「保存まで終えた」などの返答を設計します。これをここでは<strong>アプリ側ACK</strong>と呼びます。何を確認したACKなのかまで規約に含めます。単に<code>OK</code>と返すだけで、永続保存や重複防止が自動で保証されるわけではありません。</p><h2 id="部分的なsend・recvと、0・エラー" tabindex="-1">部分的なsend・recvと、0・エラー <a class="header-anchor" href="#部分的なsend・recvと、0・エラー" aria-label="Permalink to &quot;部分的なsend・recvと、0・エラー&quot;">​</a></h2><p>通常のフラグで、正のbyte数を要求するTCP通信を考えます。必要な範囲が一回で処理されるとは限りません。</p><table tabindex="0"><thead><tr><th>結果</th><th>意味と扱い</th></tr></thead><tbody><tr><td><code>send</code>が正の数<code>n</code></td><td>その<code>n</code>byte分だけ進め、未送信の残りを保持する</td></tr><tr><td><code>recv</code>が正の数<code>n</code></td><td>今回の結果は受取領域の先頭<code>n</code>byte。解析用の状態へ追加する</td></tr><tr><td>正の数を要求した<code>recv</code>が0</td><td>相手の正常な送信終了を受け、残りの受信データもなくなった</td></tr><tr><td><code>WouldBlock</code></td><td>今は進める条件がない。終了や永久的な失敗とは区別する</td></tr><tr><td>その他のエラー</td><td>リセットなどをAPIのエラーコードに従って処理する</td></tr></tbody></table><p>Winsockの<code>send</code>／<code>recv</code>は、失敗時に<code>SOCKET_ERROR</code>を返し、<code>WSAGetLastError</code>で理由を取得します。<code>WSAEWOULDBLOCK</code>はnonblockingソケットが今は待機を必要とする場合の結果です。正常な受信終了の0と、接続リセットの<code>WSAECONNRESET</code>を同じ成功として扱いません。<a href="https://learn.microsoft.com/en-us/windows/win32/api/winsock2/nf-winsock2-recv" target="_blank" rel="noreferrer">Microsoft: recv</a></p><p>C#の<code>Socket.Send</code>／<code>Socket.Receive</code>も実際数を確認します。特にnonblockingの<code>Send</code>は、要求より少ない数で成功する場合があります。使用するオーバーロードによって、エラーを<code>SocketException</code>や<code>SocketError</code>で受け取ります。<a href="https://learn.microsoft.com/en-us/dotnet/api/system.net.sockets.socket.send?view=net-10.0" target="_blank" rel="noreferrer">Microsoft: Socket.Send</a>、<a href="https://learn.microsoft.com/en-us/dotnet/api/system.net.sockets.socket.receive?view=net-10.0" target="_blank" rel="noreferrer">Socket.Receive</a></p><p>要求数0の操作を、相手の終了検査の代わりにしません。また、<strong>受信データ中の<code>00</code>は通信終了の印ではありません。</strong> byte内容とreadの実際数を分ける点は<a href="/study/os/file-read-journey.html">ファイルread</a>にも通じますが、ソケットの切断や待機には別の契約があります。</p><h2 id="tcpの上でメッセージの境界を作る" tabindex="-1">TCPの上でメッセージの境界を作る <a class="header-anchor" href="#tcpの上でメッセージの境界を作る" aria-label="Permalink to &quot;TCPの上でメッセージの境界を作る&quot;">​</a></h2><p>TCPは<code>send</code>の区切りを保存しません。ヘッダーだけが先に届く、本文が分かれる、複数メッセージが一回の<code>recv</code>に入る、という組合せをアプリが扱います。TCPセグメントの境界も、アプリのread/writeバッファ境界との対応は保証されません。<a href="https://www.rfc-editor.org/rfc/rfc9293.html#section-3.7" target="_blank" rel="noreferrer">IETF RFC 9293 §3.7: Segmentation</a></p><p>実践では、各本文の前に<strong>2byteの長さをbig-endianで置く</strong>規約を使います。長さは本文のbyte数で、2byteのヘッダー自体は含みません。これは教材が選んだアプリの規約であり、TCPがこのヘッダーを追加するわけではありません。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>長さ     本文</span></span>
<span class="line"><span>00 06 | 41 42 00 E3 81 82</span></span>
<span class="line"><span>00 04 | 10 20 30 40</span></span>
<span class="line"><span></span></span>
<span class="line"><span>送る全体は14byte:</span></span>
<span class="line"><span>00 06 41 42 00 E3 81 82 00 04 10 20 30 40</span></span></code></pre></div><p>解析側は、まず長さ用の2byteを揃え、<code>上位byte × 256 + 下位byte</code>で本文長を求めます。その長さの本文が揃ったら一件を完成させ、残りがあれば次のヘッダーへ進みます。CPUネイティブの整数表現を、そのままネットワーク形式と見なしません。<a href="/study/data/integer-bits-and-bytes.html">整数とバイト順</a>を参照してください。</p><p>受信時には、許容する本文長、蓄積量、未完了フレームの期限を設けます。宣言長を無検証で確保すると、壊れた入力が大量のメモリや待機を要求し得ます。ヘッダーや本文の途中でEOFになったら、今回の規約では未完成のメッセージです。EOFだけで正常な一件に変わるわけではありません。</p><p>実践はsend／recvの要求を最大3byteに制限して、累積処理を観察しやすくします。<strong>要求を小さくしたことは、実ネットワークのパケット分割を観測したことではありません。</strong> APIの呼出し回数、実際数、待機回数は固定の通信規約にしません。</p><h2 id="半閉鎖と、逆方向の返答" tabindex="-1">半閉鎖と、逆方向の返答 <a class="header-anchor" href="#半閉鎖と、逆方向の返答" aria-label="Permalink to &quot;半閉鎖と、逆方向の返答&quot;">​</a></h2><p>TCPは双方向です。一方がもう送らないことと、逆方向のデータも受け取れないことを分けられます。<strong>送信側の半閉鎖</strong>では、Winsockの<code>shutdown(SD_SEND)</code>、C#の<code>Shutdown(SocketShutdown.Send)</code>で以後の送信を終了し、受信は続けます。<a href="https://learn.microsoft.com/en-us/windows/win32/api/winsock2/nf-winsock2-shutdown" target="_blank" rel="noreferrer">Microsoft: shutdown</a>、<a href="https://learn.microsoft.com/en-us/dotnet/api/system.net.sockets.socket.shutdown?view=net-10.0" target="_blank" rel="noreferrer">Socket.Shutdown</a></p><p>実践の順序は次のとおりです。</p><ol><li>クライアントが14byteをすべてsendへ受け入れてもらい、送信側を半閉鎖する。</li><li>サーバー側が2フレームを解析し、<code>recv</code>の0でクライアントの送信終了まで確認する。</li><li>サーバーがアプリ側ACKとして<code>4F 4B 00 01</code>の4byteを返し、自分の送信側も半閉鎖する。</li><li>クライアントがACKの内容と、その後の受信終了を確認する。</li></ol><p>この4byteは独自の固定返答で、上の長さ付きフレームとは別に定めています。途中の<code>00</code>もデータです。ここでのACKは「2フレームと送信終了を検証した」という教材上の返答で、ゲーム内処理や保存を行うものではありません。</p><figure class="study-figure"><img src="`+a+'" alt="14byteのストリームから2byteの長さ付き本文6byteと4byteを復元し、クライアントの送信半閉鎖後もサーバーから4byteのアプリ側ACKを返せることを示す図。recv境界やパケット境界はフレーム境界として扱わない。" width="760" height="1510"><figcaption><strong>フレームの完成、相手の送信終了、逆方向の返答を別に確認する。</strong> <code>shutdown</code>自体はソケットの解放ではありません。最後はC++の<code>closesocket</code>やC#の<code>Dispose</code>で所有資源を解放します。<a href="/study/images/network/tcp-framing-and-half-close.svg" target="_blank" rel="noopener noreferrer">境界と半閉鎖の図を拡大</a></figcaption></figure><h2 id="nonblocking、待機、期限" tabindex="-1">nonblocking、待機、期限 <a class="header-anchor" href="#nonblocking、待機、期限" aria-label="Permalink to &quot;nonblocking、待機、期限&quot;">​</a></h2><p>nonblockingは「今は進まない操作を、無期限に待ち続けず結果として返す」設定です。常にデータがあることや、処理全体が別スレッドで進むことを意味しません。nonblockingの<code>connect</code>も即時成功だけでなく、接続中の状態を返すため、その後の成立や失敗を確認します。<a href="https://learn.microsoft.com/en-us/windows/win32/api/winsock2/nf-winsock2-connect" target="_blank" rel="noreferrer">Microsoft: connect</a></p><p>Windowsの<code>select</code>やC#の<code>Poll</code>は、進めそうな操作や終了を待つ道具です。<strong>readableは、完全な一件のメッセージが届いたという通知ではありません。</strong> データだけでなく切断やリセットの場合もあるため、実際の<code>recv</code>結果を読みます。これらの待機呼出し自体は、呼出しスレッドを待機させる場合があります。<a href="https://learn.microsoft.com/en-us/windows/win32/api/winsock2/nf-winsock2-select" target="_blank" rel="noreferrer">Microsoft: select</a>、<a href="https://learn.microsoft.com/en-us/dotnet/api/system.net.sockets.socket.poll?view=net-10.0" target="_blank" rel="noreferrer">Socket.Poll</a></p><p>実践は単一スレッドで接続や送受信を進め、nonblockingと有限の待機を組み合わせます。期限は、時刻補正で前後しない単調な経過時間を基準にした<strong>絶対期限</strong>で管理し、繰返しのたびに待ち時間を最初から延ばしません。C++の<code>steady_clock</code>や、WindowsでのQPCを基準にした経過時間と、日時を表す時計を区別します。ただしOSのスケジュールや待機精度があるため、正確な実時間で必ず復帰する保証ではありません。<a href="https://timsong-cpp.github.io/cppwp/n4861/time.clock.steady" target="_blank" rel="noreferrer">C++20草案 N4861: steady_clock</a>、<a href="https://learn.microsoft.com/en-us/windows/win32/sysinfo/acquiring-high-resolution-time-stamps" target="_blank" rel="noreferrer">Microsoft: 高精度の時刻と経過時間</a></p><p><strong>期限切れは、データが相手へ全く届かなかった証明ではありません。</strong> 相手が処理した後に返答だけ失われた場合も、まだ処理していない場合も区別できないことがあります。再接続して同じ購入や保存要求を再試行する設計なら、要求ID、重複の記録、同じ要求を二度適用しない規約などを別途考えます。TCP内部の再送と、アプリによる要求の再実行は別です。</p><h2 id="ゲームへの接続と実践の範囲" tabindex="-1">ゲームへの接続と実践の範囲 <a class="header-anchor" href="#ゲームへの接続と実践の範囲" aria-label="Permalink to &quot;ゲームへの接続と実践の範囲&quot;">​</a></h2><p>受信完了を別スレッドやイベントで扱う場合も、共有状態とバッファの所有期間を決めます。<a href="/study/runtime/thread-synchronization.html">スレッド同期</a>や<a href="/study/os/asynchronous-file-io.html">非同期I/O</a>の「要求・完了・利用」を分ける考え方につながりますが、ファイルAPIの契約をソケットへそのまま移しません。</p><p>ゲームでは必要な順序、期限、再送、帯域、認証などから通信方式を選びます。UDPでは受け取るデータの区切りと失敗時の扱いが変わります。回線が混雑した場合は、転送量と遅延を分けて測ります。<a href="/study/network/udp-datagrams.html">UDPとデータグラム</a> · <a href="/study/network/latency-throughput-and-queues.html">通信の遅延と帯域</a></p><p>Webの要求・応答へ進む場合は<a href="/study/network/http-messages.html">HTTP通信</a>、名前からIP候補を得る処理は<a href="/study/network/dns-resolution.html">DNSと名前解決</a>、暗号化と相手の確認は<a href="/study/network/tls-https.html">TLS・証明書・HTTPS</a>へ進んでください。</p><p>IPアドレスが決まった後に、OSがどのインターフェースと経由先を選ぶかは、<a href="/study/network/ip-routing-and-ethernet.html">IPの経路選択とEthernet</a>で追えます。</p><p><a href="/study/practice/network/tcp-loopback-observation.html">C++とC#でTCPループバックを観察する</a>では、既知の2フレーム、部分的なAPI処理、アプリ側ACK、両方向の送信終了を照合します。実パケットの境界、再送、外部ネットワーク性能、物理NICの動作は観測対象に含めません。</p>',51)])])}const b=t(c,[["render",d]]);export{g as __pageData,b as default};
